<script setup lang="ts">import { reactive,ref } from 'vue';import { useAuthStore } from '../stores/auth';const auth=useAuthStore(),saved=ref(false);const form=reactive({name:String(auth.record?.name||''),timezone:String(auth.record?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)});async function submit(){await auth.updateProfile(form);saved.value=true;setTimeout(()=>saved.value=false,1800)}</script>
<template><section class="page narrow"><div class="page-heading"><div><p class="eyebrow">PROFILE</p><h1>個人設定</h1><p>PocketBase 內建使用者驗證與個人資料。</p></div></div><form class="card form-card" @submit.prevent="submit"><label>Email<input :value="auth.record?.email" disabled></label><label>顯示名稱<input v-model="form.name" required></label><label>時區<input v-model="form.timezone" required></label><button class="primary">儲存設定</button><span v-if="saved" class="success">已儲存</span></form></section></template>
